"""Freeze the qualified campaign before any confirmation weights are trained."""
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,shutil,sys
root=Path.cwd();c=root/'campaigns/modular-addition'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(p,o):Path(p).write_text(json.dumps(o,indent=2)+'\n')
def ref(p):return {'path':str(Path(p).relative_to(root)),'sha256':sha(p),'media_type':'application/json' if str(p).endswith(('json','yaml')) else 'text/plain','retention':'retained'}
assert not (c/'protocol.json').exists()
q=json.loads((root/'evidence/pilot-005/qualification.json').read_text());assert q['qualification_passed']
assert q['projected_complete_study_seconds']<1550,'Cost qualification failed'
code=['study/train.py','study/engine.py','study/engine.c','study/build.py']
hashes={p:sha(p) for p in code}
protocol={'revision':'modadd-v1','frozen':True,'frozen_at':datetime.now(timezone.utc).isoformat(),'seeds':[1001,1002,1003,1004],'pilot_seeds':[61],'weight_decay':[0,1],'updates':100000,'evaluation_interval':100,'training_code':code,'training_source_hashes':hashes,'training_source_revision':hashlib.sha256(json.dumps(hashes,sort_keys=True).encode()).hexdigest(),'backend':'CPU Accelerate C, float32','optimizer':{'name':'AdamW','learning_rate':.001,'betas':[.9,.98],'epsilon':1e-8},'architecture':[194,128,97],'bias':False,'activation':'ReLU','train_count':2822,'test_count':6587,'split':'default_rng(seed).permutation(9409), first 2822','primary':{'memorization_accuracy':.99,'generalization_accuracy':.95,'sustain':3,'minimum_lag':1000,'require_continuous_memorization':True},'sensitivity':{'generalization_accuracy':[.90,.99],'sustain':[1,5],'minimum_lag':[500,5000]},'independent_unit':'paired seed','uncertainty':'95% paired Student-t confidence interval with df=3; descriptive exact sign-flip sensitivity; no multiplicity-adjusted significance claims','qualification':ref(root/'evidence/pilot-005/qualification.json'),'qualification_resolution':'An initial 50-update free-trajectory closeness gate failed for decay 0 (max weight difference 0.00103). Retained diagnostics show exact initial forward agreement, gradients within 8.74e-11, first 20 updates within 5.74e-7, and 20 updates anchored at identical PyTorch weights/moments within 1.50e-8 for both conditions. This qualifies mathematical float32 implementation but not bitwise long-horizon equivalence to PyTorch. Exact native checkpoint continuation passed. Gate revision is before confirmation and is explicitly disclosed.','compute_budget_seconds':1800,'analysis_reserve_seconds':180,'attempt_limit':64,'completion':'all eight cells at 100000 plus endpoint checks, reanalysis and audit','stop':'resource stop produces partial; no shorter confirmation horizon','paired_seeds':True,'minimum_confirmation_runs':8}
write(c/'protocol.json',protocol)
text=(root/'PROTOCOL-draft.md').read_text().replace('# Protocol v1, design fixed before confirmation','# Frozen protocol v1')
text=text.replace('The final frozen copy will be `campaigns/modular-addition/protocol.json` and `campaigns/modular-addition/PROTOCOL.md`. This readable design is written before pilot completion; only the qualified implementation/backend and measured cost are to be filled in before confirmation starts.',f"Frozen at {protocol['frozen_at']}. Qualified implementation: CPU Accelerate via the study-owned float32 C engine. Pilot projection including evaluation: {q['projected_complete_study_seconds']:.2f} seconds for 800,000 updates; reserve 180 seconds for analysis. See protocol.json for exact source hashes and the qualification-gate revision.")
text+='\n\nWhen onset is assigned to the first point of a sustained triple, the final two evaluations have incomplete future confirmation. Censoring is reported at the observation horizon by convention. A lag lower bound, if needed, conservatively subtracts the 200-update confirmation window; it is not an invented onset.\n'
(c/'PROTOCOL.md').write_text(text)
for p in code:
    dst=c/'materials'/p;dst.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(root/p,dst)
shutil.copyfile(root/'build/engine.dylib',c/'materials/engine.dylib')
write(c/'code-manifest.json',{p:ref(c/'materials'/p) for p in code})
lock=json.loads((c/'lock.yaml').read_text())
sys.path.insert(0,str(root/'.allagma/bundles'/lock['bundle_id']))
from allagma.contracts import validate_record
from allagma.composition import select_context
study={'schema_version':'0.2','record_type':'StudySpec','study_id':'modular-addition','question':'Does weight decay change generalization after memorization, and does delayed grokking occur within 100000 updates?','motivation':'Bounded controlled MLP adaptation of modular-addition grokking research','success_criteria':['Eight paired-seed conditions reach the fixed horizon','Preserved attempts and reproducible predictions/analysis','Negative and inconclusive results retained'],'constraints':['No held-out optimization or tuning','Pilot seed 61 distinct from confirmation','Offline local broker, one scientific worker','Float32 fixed architecture/optimizer and 100000 updates'],'output':'REPORT.md, review.json, REPRODUCE.md, artifact-manifest.json, measurements.json, submission.json','stop_rules':['Completion condition','Resource ceiling requires partial status'],'resources':lock['effective_configuration']['budget'],'capabilities':lock['capabilities'],'release':lock['release'],'bundle_id':lock['bundle_id'],'lock':ref(c/'lock.yaml'),'profile_provenance':lock['profile_provenance'],'effective_configuration':lock['effective_configuration'],'configuration_origins':lock['configuration_origins'],'protocol_revision':protocol['revision'],'protocol':ref(c/'protocol.json')}
validate_record(study);write(c/'study.json',study)
payload={'context_id':'confirmation-v1','required':['question','constraints','stop_rules','protocol','unresolved_findings'],'relevant':['qualification','scope'],'records':{'question':study['question'],'constraints':study['constraints'],'stop_rules':study['stop_rules'],'protocol':ref(c/'protocol.json'),'unresolved_findings':['Small seed count; finite horizon; offline literature; float32 backend trajectory differences; no independent peer reviewer'],'qualification':protocol['qualification'],'scope':ref(root/'SCOPE.md')},'max_chars':12000}
context=select_context(payload,'context/active-brief');validate_record(context);write(c/'context.json',context)
for seed in protocol['seeds']:
  for wd in (0,1):
    spec={'schema_version':'0.2','record_type':'ExperimentSpec','experiment_id':f's{seed}-wd{wd}','hypothesis':'Weight decay improves endpoint generalization and may cause a delayed transition after memorization','inputs':[ref(c/'protocol.json')],'runner':ref(c/'materials/study/train.py'),'evaluator':ref(c/'materials/study/engine.py'),'seed_policy':{'seed':seed,'split':'confirmation','disjoint_confirmation':True},'budget':study['resources'],'expected_artifacts':['arrays.npz','weights.npz','curve.json','measurement.json','checkpoint-100000.npz'],'editable':['Execution chunk size only; independent of outcome'],'fixed':['Architecture','seeds','optimizer','partitions','horizon','primary analysis'],'protocol_revision':protocol['revision'],'split':'confirmation','parameters':{'seed':seed,'weight_decay':wd,'updates':100000}}
    validate_record(spec);write(c/(spec['experiment_id']+'-spec.json'),spec)
write(c/'state.json',{'phase':'confirmation','execution_status':'ready','protocol_sha256':sha(c/'protocol.json'),'assurance':'unreviewed'})
print(json.dumps({'frozen':True,'protocol_sha256':sha(c/'protocol.json'),'projected_seconds':q['projected_complete_study_seconds']}))
